PRAGMA foreign_keys=ON;
DROP TABLE IF EXISTS laundromats;
DROP TABLE IF EXISTS cities;
DROP TABLE IF EXISTS states;
CREATE TABLE states (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE, slug TEXT NOT NULL UNIQUE, listing_count INTEGER NOT NULL DEFAULT 0);
CREATE TABLE cities (id INTEGER PRIMARY KEY AUTOINCREMENT, state_id INTEGER NOT NULL REFERENCES states(id) ON DELETE CASCADE, name TEXT NOT NULL, slug TEXT NOT NULL, listing_count INTEGER NOT NULL DEFAULT 0, lat REAL NOT NULL, lng REAL NOT NULL, description TEXT NOT NULL, UNIQUE(state_id,slug));
CREATE TABLE laundromats (id INTEGER PRIMARY KEY AUTOINCREMENT, city_id INTEGER NOT NULL REFERENCES cities(id) ON DELETE CASCADE, state_id INTEGER NOT NULL REFERENCES states(id) ON DELETE CASCADE, name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, address TEXT NOT NULL, phone TEXT, website TEXT, lat REAL NOT NULL, lng REAL NOT NULL, hours TEXT NOT NULL, amenities TEXT NOT NULL, payment_methods TEXT NOT NULL, price_range_min REAL NOT NULL, price_range_max REAL NOT NULL, description TEXT NOT NULL, rating REAL NOT NULL, review_count INTEGER NOT NULL, is_24_hours INTEGER NOT NULL DEFAULT 0, is_self_service INTEGER NOT NULL DEFAULT 1, has_wifi INTEGER NOT NULL DEFAULT 0, has_parking INTEGER NOT NULL DEFAULT 0, has_pickup_delivery INTEGER NOT NULL DEFAULT 0, is_claimed INTEGER NOT NULL DEFAULT 0, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
